* var z1 = new Complex64( 5.0, 3.0 );
* var z2 = new Complex64( -2.0, 1.0 );
*
* var out = csubf( z1, z2 );
* // returns <Complex64>[ 7.0, 2.0 ]
*/
function csubf( z1, z2 ) {
	var re = f32( realf( z1 ) - realf( z2 ) );
	var im = f32( imagf( z1 ) - imagf( z2 ) );
	return new Complex64( re, im );
}


// EXPORTS //

