'use strict';

// MODULES //

var tape = require( 'tape' );
var isnanf = require( '@stdlib/math-base-assert-is-nanf' );
var Complex64 = require( '@stdlib/complex-float32-ctor' );
var realf = require( '@stdlib/complex-float32-real' );
var imagf = require( '@stdlib/complex-float32-imag' );
var csubf = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof csubf, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function subtracts two complex numbers', function test( t ) {
	var z1;
	var z2;
	var v;

	z1 = new Complex64( 5.0, 3.0 );
	z2 = new Complex64( -2.0, 1.0 );

	v = csubf( z1, z2 );

	t.strictEqual( realf( v ), 7.0, 'returns expected value' );
	t.strictEqual( imagf( v ), 2.0, 'returns expected value' );

	t.end();
});

tape( 'if a real or imaginary component is `NaN`, the resulting component is `NaN`', function test( t ) {
	var z1;
	var z2;
	var v;

	z1 = new Complex64( NaN, 3.0 );
	z2 = new Complex64( -2.0, 1.0 );

	v = csubf( z1, z2 );
	t.strictEqual( isnanf( realf( v ) ), true, 'returns expected value' );
	t.strictEqual( imagf( v ), 2.0, 'returns expected value' );

